entries[143478] = { ["name"] = "Arena Invitation", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"A carefully handwritten note, penned in the blood of the fallen.\"" }
entries[143479] = { ["name"] = "Frayed Banner", ["text"] = "Binds when picked up\n\"Blood-stained and torn, which simply adds to its splendor.\"\nSell Price:" }
entries[143486] = { ["name"] = "Arcshaper's Barrier", ["text"] = "Binds when picked up\n\"The Arcshaper fashioned the crystal well. The power, while it can be suppressed, will always remain strong.\"\nSell Price:" }
entries[143487] = { ["name"] = "Enchanted Dusk Lily", ["text"] = "Binds when picked up\n\"From time to time, Dusk Lilies can be found with a great innate power. This may be why it became such a powerful symbol.\"\nSell Price:" }
entries[143488] = { ["name"] = "Enchanted Nightborne Coin", ["text"] = "Binds when picked up\n\"Handed down for generations, this coin holds lingering knowledge from all its previous holders.\"\nSell Price:" }
entries[143489] = { ["name"] = "Raging Tempest Totem", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Farseer's Raging Tempest.\nSummons and dismisses your Farseer's Raging Tempest. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Windfury. Overload: (2).\"\nQuest:\nGathering of the Storms" }
entries[143490] = { ["name"] = "Bloody Reins of Dark Portent", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Shadowblade's Crimson Omen.\nSummons and dismisses your Shadowblade's Sanguine Omen. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The blood of your enemies won't even show up, blends right in.\"\nVendor:\nZan Shivsproket\nZone:\nDalaran" }
entries[143491] = { ["name"] = "Mephitic Reins of Dark Portent", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Shadowblade's Baneful Omen.\nSummons and dismisses your Shadowblade's Murderous Omen. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"For the toxin-inclined.\"\nVendor:\nZan Shivsproket\nZone:\nDalaran" }
entries[143492] = { ["name"] = "Midnight Black Reins of Dark Portent", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Shadowblade's Lethal Omen.\nSummons and dismisses your Shadowblade's Lethal Omen. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"They'll never hear you coming.\"\nVendor:\nZan Shivsproket\nZone:\nDalaran" }
entries[143493] = { ["name"] = "Razor-Lined Reins of Dark Portent", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Shadowblade's Murderous Omen.\nSummons and dismisses your Shadowblade's Murderous Omen. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The preferred vehicle for assassinations, they make no sounds when flying - really great for sneaking up on people.\"\nQuest:\nHiding In Plain Sight" }
entries[143494] = { ["name"] = "A Mysterious Note", ["text"] = "Quest Item\n\"It appears to be from one of the cultists Karam spoke of.\"\n<Right Click to Read>" }
