entries[143498] = { ["name"] = "Charged Construct's Finger", ["text"] = "Binds when picked up\n\"The Magistrix is getting reckless. The devastating power that thing has in its pinky alone could have leveled half the palace.\"\nSell Price:" }
entries[143499] = { ["name"] = "Overcharged Infiltrator's Mask", ["text"] = "Binds when picked up\n\"Hastily put together, this mask was infused with too much power and is coming apart at the seams.\"\nSell Price:" }
