entries[143502] = { ["name"] = "Glowing Reins of the Golden Charger", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon a Highlord's Golden Charger.\nSummons and dismisses your Highlord's Golden Charger. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The fanciest of all of the horses.\"\nQuest:\nStirring in the Shadows" }
