entries[143533] = { ["name"] = "Infused Pit Lord Tusk", ["text"] = "Binds when picked up\n\"Already a powerful demon, Rozzeleth appears to have absorbed a lot of Ancient Mana while stationed in Suramar. Severed from his fel form his tusk hums with it.\"\nSell Price:" }
