entries[143538] = { ["name"] = "Entangled Telemancy Orb", ["text"] = "Binds when picked up\n\"Containing all possible telemancy results at once, theoretically it could take you exactly where you needed to go. In practice it only seemed reliable for when nature was calling.\"\nSell Price:" }
